import { extractIsbn, extractAuthor, removeIsbnFromTitle, normalizeIsbn } from "./book-matching.mjs";
import { findBookByIsbn } from "./book-providers.mjs";
import { mergeExactIsbnMetadata } from "./book-metadata-merge.mjs";

const API = "https://api.github.com";
const MARKER = "<!-- This comment is autogenerated by the Libros metadata resolver -->";
const TOKEN = process.env.GITHUB_TOKEN;
const REPOSITORY = process.env.GITHUB_REPOSITORY;
const REQUESTED_ISSUE = process.env.ISSUE_NUMBER?.trim();

if (!TOKEN || !REPOSITORY) {
  throw new Error("GITHUB_TOKEN and GITHUB_REPOSITORY are required.");
}

async function request(path, options = {}) {
  const response = await fetch(`${API}/repos/${REPOSITORY}${path}`, {
    ...options,
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: `Bearer ${TOKEN}`,
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
    signal: AbortSignal.timeout(20_000),
  });
  const body = await response.text();
  if (!response.ok) throw new Error(`GitHub API ${response.status} for ${path}: ${body}`);
  return body ? JSON.parse(body) : null;
}

async function getAllPages(path) {
  const values = [];
  for (let page = 1; ; page += 1) {
    const separator = path.includes("?") ? "&" : "?";
    const batch = await request(`${path}${separator}per_page=100&page=${page}`);
    values.push(...batch);
    if (batch.length < 100) return values;
  }
}

function parseBookDetails(commentBody) {
  const match = commentBody.match(/<summary>Book details \(JSON\)<\/summary>[\s\S]*?\`\`\`json\s*([\s\S]*?)\`\`\`/);
  if (!match) return null;
  try {
    return JSON.parse(match[1]);
  } catch {
    return null;
  }
}

function getCommentBody(book, requestedIsbn, previousDetails) {
  const sourceName = book.googleBooks?.id
    ? "Google Books"
    : book.googleBooks?.info?.includes("planetadelibros.com")
      ? "PlanetadeLibros"
      : "Open Library";
  const sourceUrl = book.googleBooks?.info || book.googleBooks?.canonical || "";
  const details = {
    ...book,
    ...(requestedIsbn ? { requestedIsbn } : {}),
    metadataSource: requestedIsbn ? "Exact ISBN match; existing metadata refreshed" : "Existing metadata retained; ISBN unavailable",
    ...(previousDetails?.goodreads ? { goodreads: previousDetails.goodreads } : {}),
  };

  return [
    MARKER,
    "",
    `Book match: **${book.title}** by ${book.authors?.join(", ") || "unknown author"}.`,
    requestedIsbn ? `Matched using exact ISBN ${requestedIsbn}; missing metadata was supplemented without changing the edition.` : "No ISBN was available, so the existing metadata was retained.",
    sourceUrl ? `Source: [${sourceName}](${sourceUrl}).` : "",
    "",
    "<details>",
    "<summary>Book details (JSON)</summary>",
    "",
    "```json",
    JSON.stringify(details, null, 2),
    "```",
    "",
    "</details>",
    "",
    "When you finish reading, close this issue to mark it as completed. 👍",
  ].filter(Boolean).join("\n");
}

function isBookIssue(issue) {
  return !issue.pull_request && issue.labels?.some((label) => label.name === "kind: book");
}

async function refreshIssue(issue) {
  const comments = await getAllPages(`/issues/${issue.number}/comments`);
  const generated = comments.filter((comment) => comment.body?.includes(MARKER)).at(-1);
  if (!generated) return { issue: issue.number, status: "skipped", reason: "No autogenerated metadata comment" };

  const previous = parseBookDetails(generated.body);
  if (!previous) return { issue: issue.number, status: "skipped", reason: "Could not parse existing metadata JSON" };

  const requestedIsbn = extractIsbn(previous.requestedIsbn || issue.title || issue.body || "")
    || extractIsbn(previous.isbn13 || "")
    || extractIsbn(previous.isbn10 || "");
  let fresh;

  if (requestedIsbn) {
    fresh = await findBookByIsbn(requestedIsbn);
    if (!fresh) return { issue: issue.number, status: "skipped", reason: `No exact match found for ISBN ${requestedIsbn}` };
    const returnedIsbns = [fresh.isbn10, fresh.isbn13].filter(Boolean).map(normalizeIsbn);
    const requestedNormalized = normalizeIsbn(requestedIsbn);
    if (!returnedIsbns.includes(requestedNormalized)) {
      return { issue: issue.number, status: "skipped", reason: "Provider result did not confirm the requested ISBN" };
    }
  } else {
    // Do not replace an edition when no ISBN is available; wait for manual verification.
    return { issue: issue.number, status: "skipped", reason: "No ISBN; manual edition verification required" };
  }

  const merged = mergeExactIsbnMetadata(previous, fresh);
  merged.title = previous.title || fresh.title;
  merged.authors = previous.authors?.length ? previous.authors : fresh.authors;
  merged.requestedIsbn = requestedIsbn;
  merged.metadataSource = "Exact ISBN match; existing metadata refreshed";

  const newBody = getCommentBody(merged, requestedIsbn, previous);
  if (newBody === generated.body) {
    return { issue: issue.number, status: "unchanged", title: issue.title };
  }

  await request(`/issues/comments/${generated.id}`, {
    method: "PATCH",
    body: JSON.stringify({ body: newBody }),
  });
  return { issue: issue.number, status: "updated", title: issue.title };
}

async function main() {
  const issues = REQUESTED_ISSUE
    ? [await request(`/issues/${Number(REQUESTED_ISSUE)}`)]
    : await getAllPages("/issues?state=all&sort=created&direction=asc");

  const books = issues.filter(isBookIssue);
  const summary = { updated: 0, unchanged: 0, skipped: 0, errors: 0 };
  console.log(`Found ${books.length} book issues to inspect.`);

  for (const issue of books) {
    try {
      const result = await refreshIssue(issue);
      summary[result.status] += 1;
      console.log(JSON.stringify(result));
    } catch (error) {
      summary.errors += 1;
      console.error(JSON.stringify({ issue: issue.number, status: "error", message: error.message }));
    }
  }

  console.log("Refresh summary:", JSON.stringify(summary));
  if (summary.errors > 0) process.exitCode = 1;
}

await main();
